def _copilot_fallback_command(
    *,
    codex: str | None,
    copilot: str,
    workspace_path: Path,
    codex_context_window: int | None = None,
) -> list[str]:
    """Build a bash command that tries Codex first, falls back to Copilot CLI.

    Both tools are invoked with full capability flags:
    - Codex: model selection, reasoning effort, context window, sub-agent threading
    - Copilot: model selection, reasoning effort, long context, autopilot with continuation limit
    """
    # Codex configuration
    codex_model = (
        os.environ.get(_CODEX_MODEL_ENV, "").strip()
        or DEFAULT_CODEX_MODEL
    )
    codex_context = (
        str(codex_context_window)
        if codex_context_window is not None
        else os.environ.get(_CODEX_CONTEXT_WINDOW_ENV, "200000").strip()
    )
    codex_reasoning = (
        os.environ.get(_CODEX_REASONING_EFFORT_ENV, "").strip()
        or DEFAULT_CODEX_REASONING_EFFORT
    )
    codex_max_threads = os.environ.get(_CODEX_MAX_THREADS_ENV, "10").strip()
    codex_max_depth = os.environ.get(_CODEX_MAX_DEPTH_ENV, "2").strip()

    # Copilot configuration
    copilot_model = os.environ.get(_COPILOT_MODEL_ENV, "").strip()
    copilot_effort = os.environ.get(_COPILOT_EFFORT_ENV, "high").strip()
    copilot_context = os.environ.get(_COPILOT_CONTEXT_TIER_ENV, "long_context").strip()
    copilot_max_continues = os.environ.get(_COPILOT_MAX_CONTINUES_ENV, "30").strip()

    return [
        "bash",
        "-lc",
        """
prompt_file=$(mktemp)
trap 'rm -f "$prompt_file"' EXIT
cat > "$prompt_file"
codex_bin="$1"
copilot_bin="$2"
workspace="$3"
codex_model="$4"
codex_context="$5"
codex_reasoning="$6"
codex_max_threads="$7"
codex_max_depth="$8"
copilot_model="$9"
copilot_effort="${10}"
copilot_context="${11}"
copilot_max_continues="${12}"

if [[ -n "$codex_bin" ]]; then
    codex_args=(exec --dangerously-bypass-approvals-and-sandbox -C "$workspace")
    # Model selection
    [[ -n "$codex_model" ]] && codex_args+=(-m "$codex_model")
    # Context window, reasoning, and sub-agent configuration via -c overrides
    [[ -n "$codex_context" ]] && codex_args+=(-c "model_context_window=$codex_context")
    [[ -n "$codex_reasoning" ]] && codex_args+=(-c "model_reasoning_effort=\"$codex_reasoning\"")
    [[ -n "$codex_max_threads" ]] && codex_args+=(-c "agents.max_threads=$codex_max_threads")
    [[ -n "$codex_max_depth" ]] && codex_args+=(-c "agents.max_depth=$codex_max_depth")
    codex_args+=(-)

    if "${codex_bin}" "${codex_args[@]}" < "$prompt_file"; then
        exit 0
    else
        rc=$?
        printf 'codex exec failed with exit %s; falling back to copilot\\n' "$rc" >&2
    fi
fi

copilot_args=(--silent --allow-all-tools --allow-all-paths --no-ask-user --autopilot)
# Model selection
[[ -n "$copilot_model" ]] && copilot_args+=(--model="$copilot_model")
# Reasoning effort
[[ -n "$copilot_effort" ]] && copilot_args+=(--effort="$copilot_effort")
# Long context tier (1M tokens)
[[ -n "$copilot_context" ]] && copilot_args+=(--context "$copilot_context")
# Autopilot continuation limit (safety cap)
[[ -n "$copilot_max_continues" ]] && copilot_args+=(--max-autopilot-continues "$copilot_max_continues")
copilot_args+=(--prompt "$(cat "$prompt_file")")

exec "$copilot_bin" "${copilot_args[@]}"
""",
        "bash",
        codex or "",
        copilot,
        str(workspace_path),
        codex_model,
        codex_context,
        codex_reasoning,
        codex_max_threads,
        codex_max_depth,
        copilot_model,
        copilot_effort,
        copilot_context,
        copilot_max_continues,
    ]


def split_csv(value: str) -> list[str]:
    raw = [item.strip() for item in value.split(",")]
    return [item for item in raw if item and item.lower() not in {"none", "n/a"}]


def normalize_status(value: str) -> str:
    lowered = str(value or "").strip().lower().replace("-", "_").replace(" ", "_")
    if lowered in {"done", "complete", "completed"}:
        return "completed"
    if lowered in {"blocked", "on_hold"}:
        return "blocked"
    if lowered in {"active", "in_progress"}:
        return "in_progress"
    if lowered in {"ready", "todo", "queued", "pending", ""}:
        return "todo"
    return lowered


def normalize_task_header_prefix(value: str) -> str:
    stripped = value.strip()
    if stripped.startswith("## "):
        return stripped
    return f"## {stripped}"


RETRY_BUDGET_REPAIR_TITLE_RE = re.compile(
    r"^Resolve\s+(?P<kind>validation|implementation|merge)\s+retry-budget\s+failure\s+for\s+(?P<source>[A-Z][A-Z0-9]*-\d+)\b",
    re.IGNORECASE,
)
RETRY_BUDGET_REPAIR_ACCEPTANCE_RE = re.compile(
    r"\b(?:release|remove)\s+(?P<source>[A-Z][A-Z0-9]*-\d+)\s+from\s+(?:the\s+)?strategy\s+blocked_tasks\b",
    re.IGNORECASE,
)
RETRY_BUDGET_REPAIR_SCHEMA = (
    "ipfs_accelerate_py.agent_supervisor.retry-budget-repair@1"
)
RECONCILIATION_GUARDRAIL_SCHEMA = (
    "ipfs_accelerate_py.agent_supervisor.reconciliation-guardrail@1"
)
RECONCILIATION_RESOLUTION_SCHEMA = (
    "ipfs_accelerate_py.agent_supervisor.reconciliation-resolution@1"
)


def retry_budget_repair_source(task: Any) -> tuple[str, str]:
    """Return ``(source_task_id, failure_kind)`` for generated retry repairs."""

    title_match = RETRY_BUDGET_REPAIR_TITLE_RE.search(str(getattr(task, "title", "") or ""))
    acceptance_match = RETRY_BUDGET_REPAIR_ACCEPTANCE_RE.search(str(getattr(task, "acceptance", "") or ""))
    if not title_match or not acceptance_match:
        return "", ""
    source_task_id = str(title_match.group("source") or "").strip()
    acceptance_source = str(acceptance_match.group("source") or "").strip()
    if source_task_id != acceptance_source:
        return "", ""
    failure_kind = str(title_match.group("kind") or "retry").strip().lower()

    # New repair tasks carry explicit, machine-readable provenance.  Retain
    # compatibility with older appendices, but fail closed when any explicit
    # provenance field disagrees with the independently parsed title and
    # acceptance contract.
    raw_metadata = getattr(task, "metadata", {}) or {}
    metadata = (
        {
            str(key).strip().lower().replace("_", " "): str(value).strip()
            for key, value in raw_metadata.items()
            if str(value).strip()
        }
        if isinstance(raw_metadata, Mapping)
        else {}
    )
    explicit = {
        "generated by": metadata.get("generated by", ""),
        "retry repair source": metadata.get("retry repair source", ""),
        "retry failure kind": metadata.get("retry failure kind", ""),
    }
    if any(explicit.values()) and explicit != {
        "generated by": RETRY_BUDGET_REPAIR_SCHEMA,
        "retry repair source": source_task_id,
        "retry failure kind": failure_kind,
    }:
        return "", ""
    return source_task_id, failure_kind


def is_retry_budget_repair_task(task: Any) -> bool:
    """Return whether a task is itself a generated retry-budget repair."""

    return bool(retry_budget_repair_source(task)[0])


def pending_retry_budget_repair_sources(
    tasks: Sequence[Any],
    *,
    completed_task_ids: Sequence[str] = (),
) -> set[str]:
    """Return source tasks blocked by an unfinished board-visible repair.

    Retry-budget strategies are intentionally lane-local, while the taskboard
    is shared by every lane. Deriving this fence from the shared taskboard
    prevents another lane from immediately reclaiming a source task after a
    peer has emitted its repair task.
    """

    completed = {
        str(task_id).strip()
        for task_id in completed_task_ids
        if str(task_id).strip()
    }
    completed.update(
        str(getattr(task, "task_id", "") or "").strip()
        for task in tasks
        if normalize_status(str(getattr(task, "status", "") or ""))
        == "completed"
    )
    blocked: set[str] = set()
    for task in tasks:
        task_id = str(getattr(task, "task_id", "") or "").strip()
        if not task_id or task_id in completed:
            continue
        source_task_id, _failure_kind = retry_budget_repair_source(task)
        if source_task_id and source_task_id not in completed:
            blocked.add(source_task_id)
    return blocked


def normalize_retry_validation_path(value: Any) -> str:
    """Normalize one inferred validation target without permitting escape."""

    normalized = str(value or "").strip().replace("\\", "/")
    while normalized.startswith("./"):
        normalized = normalized[2:]
    path = PurePosixPath(normalized)
    if (
        not normalized
        or path.is_absolute()
        or path.as_posix() in {".", ".."}
        or ".." in path.parts
        or (path.parts and path.parts[0].endswith(":"))
    ):
        return ""
    return path.as_posix()


def validation_command_working_prefix(command: str) -> str:
    """Return a safe package working prefix declared by a test command."""

    try:
        tokens = shlex.split(str(command or ""), posix=True)
    except ValueError:
        return ""
    for index, token in enumerate(tokens):
        raw_prefix = ""
        if token in {"--prefix", "--cwd", "--dir"} and index + 1 < len(tokens):
            raw_prefix = tokens[index + 1]
        elif token.startswith(("--prefix=", "--cwd=", "--dir=")):
            raw_prefix = token.split("=", 1)[1]
        elif token == "cd" and index + 1 < len(tokens):
            raw_prefix = tokens[index + 1]
        if not raw_prefix:
            continue
        normalized = normalize_retry_validation_path(raw_prefix)
        if normalized:
            return normalized
    return ""


def normalize_reported_test_failure_path(command: str, value: Any) -> str:
    """Resolve one runner-relative failure path to the repository root."""

    normalized = normalize_retry_validation_path(value)
    if not normalized:
        return ""
    prefix = validation_command_working_prefix(command)
    if (
        prefix
        and normalized != prefix
        and not normalized.startswith(f"{prefix}/")
    ):
        normalized = normalize_retry_validation_path(f"{prefix}/{normalized}")
    return normalized


def unsafe_validation_path_aliases(command: str) -> set[str]:
    """Return normalized aliases derived from absolute or escaping arguments.

    ``infer_validation_impact_paths`` intentionally removes a leading slash
    for changed-file matching.  Authorization must retain that distinction,
    so repair scopes conservatively exclude aliases whose raw argument was
    absolute, drive-qualified, or traversed above the repository root.
    """

    try:
        tokens = shlex.split(str(command or ""), posix=True)
    except ValueError:
        return set()
    aliases: set[str] = set()
    for token in tokens:
        raw = token.split("::", 1)[0].strip().replace("\\", "/")
        path = PurePosixPath(raw)
        if not (
            path.is_absolute()
            or ".." in path.parts
            or (path.parts and path.parts[0].endswith(":"))
        ):
            continue
        alias = raw.lstrip("/")
        while alias.startswith("./"):
            alias = alias[2:]
        if alias:
            aliases.add(PurePosixPath(alias).as_posix())
    return aliases


def retry_budget_repair_validation_paths(task: Any) -> tuple[str, ...]:
    """Return bounded repository-relative diagnostic targets for a repair."""

    if not is_retry_budget_repair_task(task):
        return ()
    metadata = {
        str(key).strip().lower().replace("_", " "): str(value or "").strip()
        for key, value in (getattr(task, "metadata", {}) or {}).items()
    }
    if "validation failure paths" in metadata:
        paths: list[str] = []
        for raw_path in split_csv(metadata["validation failure paths"]):
            normalized = normalize_retry_validation_path(raw_path)
            if normalized and normalized not in paths:
                paths.append(normalized)
        return tuple(paths)
    paths: list[str] = []
    for command in getattr(task, "validation", ()) or ():
        unsafe_aliases = unsafe_validation_path_aliases(str(command))
        for path in infer_validation_impact_paths(str(command)):
            normalized = normalize_retry_validation_path(path)
            if not normalized or normalized in unsafe_aliases:
                continue
            if normalized not in paths:
                paths.append(normalized)
    return tuple(paths)


def implied_validation_test_output_paths(
    task: Any,
    *,
    repo_root: Path,
) -> tuple[str, ...]:
    """Return absent explicit test targets implied by a task's validation.

    A task contract which invokes an explicit test file must either inherit
    that file from the baseline or permit the implementation to create it.
    Treating an absent target as read-only guarantees a late pytest usage
    error and wastes the task's retry budget. Only safe repository-relative
    Python test paths are inferred here; broad commands and production paths
    remain outside the implementation authority.
    """

    declared_outputs = {
        normalize_retry_validation_path(path)
        for path in task_declared_output_paths(task)
    }
    protected_aliases: set[str] = set()
    paths: list[str] = []
    for command in getattr(task, "validation", ()) or ():
        protected_aliases.update(unsafe_validation_path_aliases(str(command)))
        for raw_path in infer_validation_impact_paths(str(command)):
            normalized = normalize_retry_validation_path(raw_path)
            if (
                not normalized
                or normalized in protected_aliases
                or normalized in declared_outputs
                or (repo_root / normalized).exists()
            ):
                continue
            candidate = PurePosixPath(normalized)
            test_named = (
                candidate.name.startswith("test_")
                or any(part in {"test", "tests"} for part in candidate.parts)
            )
            if (
                candidate.suffix not in {".py", ".pyi"}
                or not test_named
            ):
                continue
            if normalized not in paths:
                paths.append(normalized)
    return tuple(paths)


def write_text_atomic(path: Path, content: str, *, encoding: str = "utf-8") -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    if path.is_dir():
        backup_path = unique_backup_path(path, "directory-backup")
        path.rename(backup_path)
    fd, temp_path = tempfile.mkstemp(prefix=f".{path.name}.", suffix=".tmp", dir=str(path.parent))
    try:
        with os.fdopen(fd, "w", encoding=encoding) as fh:
            fh.write(content)
        os.replace(temp_path, path)
    finally:
        try:
            os.unlink(temp_path)
        except FileNotFoundError:
            pass


def write_json_atomic(path: Path, payload: Any) -> None:
    if isinstance(payload, dict):
        _shared_atomic_write_json(path, payload)
        return
    write_text_atomic(path, json.dumps(payload, indent=2, sort_keys=True), encoding="utf-8")


def write_json_atomic_if_changed(path: Path, payload: Any) -> bool:
    """Atomically persist canonical JSON only when its bytes changed."""

    rendered = json.dumps(payload, indent=2, sort_keys=True) + "\n"
    try:
        if path.is_file() and path.read_text(encoding="utf-8") == rendered:
            return False
    except (OSError, UnicodeDecodeError):
        pass
    write_text_atomic(path, rendered, encoding="utf-8")
    return True


def load_json_dict(path: Path) -> dict[str, Any] | None:
    if not path.exists():
        return None
    try:
        text = path.read_text(encoding="utf-8").strip()
    except OSError:
        return None
    if not text:
        return None
    try:
        payload = json.loads(text)
    except json.JSONDecodeError:
        return None
    if not isinstance(payload, dict):
        return None
    return payload


def process_is_running(pid: int) -> bool:
    if pid <= 0:
        return False
    return _shared_pid_alive(pid)


def process_command_line(pid: int) -> str:
    return _shared_process_args(pid)


def parse_timestamp(value: str) -> datetime | None:
    if not value:
        return None
    try:
        parsed = datetime.fromisoformat(value)
    except ValueError:
        return None
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=timezone.utc)
    return parsed


def _provider_capacity_now() -> datetime:
    return datetime.now(timezone.utc)


def parse_provider_declared_retry_at(
    text: str,
    *,
    now: datetime | None = None,
) -> datetime | None:
    """Return the latest valid future provider reset declared in ``text``.

    Provider CLIs currently emit English reset horizons without a timezone,
    for example ``try again at Aug 5th, 2026 4:09 AM``. Treat an omitted
    timezone as UTC so the persisted deadline is deterministic across lanes.
    """

    reference = now or _provider_capacity_now()
    if reference.tzinfo is None:
        reference = reference.replace(tzinfo=timezone.utc)
    else:
        reference = reference.astimezone(timezone.utc)
    candidates: list[datetime] = []
    for match in PROVIDER_DECLARED_RETRY_AT_PATTERN.finditer(str(text or "")):
        month = PROVIDER_RETRY_MONTHS.get(
            str(match.group("month") or "").lower()[:3]
        )
        if month is None:
            continue
        meridiem = re.sub(
            r"[^apm]",
            "",
            str(match.group("meridiem") or "").lower(),
        )
        hour = int(match.group("hour"))
        if meridiem == "pm" and hour != 12:
            hour += 12
        elif meridiem == "am" and hour == 12:
            hour = 0
        timezone_text = str(match.group("timezone") or "").upper()
        declared_timezone = timezone.utc
        if timezone_text and timezone_text not in {"Z", "UTC", "GMT"}:
            compact_offset = timezone_text.replace(":", "")
            sign = 1 if compact_offset.startswith("+") else -1
            try:
                offset_hours = int(compact_offset[1:3])
                offset_minutes = int(compact_offset[3:5])
                if offset_hours > 23 or offset_minutes > 59:
                    continue
                declared_timezone = timezone(
                    sign
                    * timedelta(
                        hours=offset_hours,
                        minutes=offset_minutes,
                    )
                )
            except (ValueError, OverflowError):
                continue
        try:
            candidate = datetime(
                int(match.group("year")),
                month,
                int(match.group("day")),
                hour,
                int(match.group("minute")),
                int(match.group("second") or 0),
                tzinfo=declared_timezone,
            ).astimezone(timezone.utc)
        except (ValueError, OverflowError):
            continue
        if candidate > reference:
            candidates.append(candidate)
    return max(candidates) if candidates else None


def _provider_labels_from_implementation_command(
    command: str | Sequence[Any],
) -> list[str]:
    """Infer only providers named by the concrete implementation command."""

    if isinstance(command, str):
        try:
            items = shlex.split(command)
        except ValueError:
            return []
    else:
        items = [str(item) for item in command]
    labels: list[str] = []
    for item in items:
        lowered = str(item or "").strip().lower()
        if not lowered:
            continue
        basename = Path(lowered).name
        normalized = basename.removesuffix(".exe")
        provider_labels: tuple[str, ...] = ()
        if normalized == "codex":
            provider_labels = ("codex",)
        elif normalized in {"copilot", "github-copilot"}:
            provider_labels = ("copilot",)
        elif (
            normalized in {"grok", "grok-cli", "grok_cli_runner.py"}
            or lowered.endswith(".grok_cli_runner")
        ):
            provider_labels = ("grok",)
        elif (
            normalized in {
                "goose",
                "goose-cli",
                "meta_spark_goose_runner.py",
            }
            or lowered.endswith(".meta_spark_goose_runner")
        ):
            provider_labels = ("goose", "meta_spark")
        elif normalized in {
            "claude",
            "claude-code",
            "claude_code",
            "anthropic",
        }:
            provider_labels = ("claude",)
        elif normalized in {
            "gemini",
            "gemini-cli",
            "gemini_cli",
            "google-gemini",
        }:
            provider_labels = ("gemini",)
        elif normalized == "npx" and any(
            "@google/gemini-cli" in str(item or "").lower() for item in items
        ):
            provider_labels = ("gemini",)
        elif normalized in {"vibe", "mistral", "mistral-vibe", "mistral_vibe"}:
            provider_labels = ("mistral",)
        elif normalized in {"copilot", "github-copilot"}:
            # also matched above; keep for explicit secondary token scans
            provider_labels = ("copilot",)
        for provider in provider_labels:
            if provider not in labels:
                labels.append(provider)
    return labels


def _provider_capacity_family(label: Any) -> str:
    """Normalize one provider label to its independently latched family."""

    normalized = str(label or "").strip().lower().replace("-", "_")
    return PROVIDER_CAPACITY_FAMILY_ALIASES.get(normalized, normalized)


def classify_provider_capacity_failure(
    text: str,
    *,
    provider_labels: Sequence[str] = (),
) -> dict[str, Any]:
    """Classify provider quota/capacity failures without treating them as code failures."""

    # Worktree pool races can dispose the workspace between setup and provider
    # launch. That is infrastructure, not an implementation attempt to charge.
    if re.search(r"workspace is not a directory", text, re.IGNORECASE):
        return {
            "exhausted": True,
            "providers": ["infrastructure"],
            "reason": "workspace_missing_before_provider",
        }

    providers = [provider for provider, pattern in PROVIDER_CAPACITY_PATTERNS if pattern.search(text)]
    unique_providers = list(dict.fromkeys(providers))
    command_providers = list(
        dict.fromkeys(
            str(provider).strip().lower()
            for provider in provider_labels
            if str(provider).strip()
        )
    )
    if command_providers and unique_providers:
        attributed = [
            provider
            for provider in unique_providers
            if provider != "provider" and provider in command_providers
        ]
        if not attributed and "provider" in unique_providers:
            attributed = command_providers
        unique_providers = attributed
    result = {
        "exhausted": bool(unique_providers),
        "providers": unique_providers,
        "reason": "provider_capacity_exhausted" if unique_providers else "",
    }
    if unique_providers:
        result["failure_class"] = "transient_capacity"
    retry_at = parse_provider_declared_retry_at(text)
    if unique_providers and retry_at is not None:
        result["retry_at"] = retry_at.isoformat()
        result["retry_at_source"] = "provider_declared"
    return result


@dataclass(frozen=True)
class _SubmoduleMergeSnapshot:
    source: Path
    parent_repo: Path
    relative: str
    source_ref: str
    source_head: str
    source_status: bytes
    parent_head: str
    parent_status: bytes
    parent_index: bytes
    parent_gitlink: str


@dataclass(frozen=True)
class ImplementationDiagnosticReceipt:
    """Content-addressed, replay-safe diagnosis for one failed attempt."""

    prior_decision_id: str
    repository_id: str
    tree_id: str
    failure: Mapping[str, Any]
    changed_files: tuple[str, ...] = ()
    changed_symbols: tuple[str, ...] = ()
    unresolved_requirements: tuple[str, ...] = ()

    SCHEMA = (
        "ipfs_accelerate_py/agent-supervisor/"
        "implementation-diagnostic-receipt@1"
    )

    def __post_init__(self) -> None:
        for name in ("prior_decision_id", "repository_id", "tree_id"):
            value = str(getattr(self, name) or "").strip()
            if not value:
                raise ValueError(f"{name} is required")
            object.__setattr__(self, name, value)
        if not isinstance(self.failure, Mapping) or not self.failure:
            raise ValueError("failure must be a non-empty mapping")
        # Canonical serialization rejects non-JSON values and mutable aliases.
        failure = json.loads(canonical_json(dict(self.failure)))
        object.__setattr__(self, "failure", failure)
        for name in (
            "changed_files",
            "changed_symbols",
            "unresolved_requirements",
        ):
            values = tuple(
                sorted(
                    {
                        str(item).strip()
                        for item in getattr(self, name)
                        if str(item).strip()
                    }
                )
            )
            if len(values) > 256:
                raise ValueError(f"{name} exceeds its item limit")
            object.__setattr__(self, name, values)
        if any(
            path.startswith("/") or ".." in path.split("/")
            for path in self.changed_files
        ):
            raise ValueError(
                "changed_files must contain repository-relative paths"
            )

    @property
    def receipt_id(self) -> str:
        return content_identity(self.to_dict())

    @property
    def failure_id(self) -> str:
        return content_identity(self.failure)

    def to_dict(self) -> dict[str, Any]:
        return {
            "schema": self.SCHEMA,
            "prior_decision_id": self.prior_decision_id,
            "repository_id": self.repository_id,
            "tree_id": self.tree_id,
            "failure": dict(self.failure),
            "failure_id": self.failure_id,
            "changed_files": list(self.changed_files),
            "changed_symbols": list(self.changed_symbols),
            "unresolved_requirements": list(self.unresolved_requirements),
        }

    def to_record(self) -> dict[str, Any]:
        return {**self.to_dict(), "receipt_id": self.receipt_id}

    @classmethod
    def from_dict(
        cls, payload: Mapping[str, Any]
    ) -> "ImplementationDiagnosticReceipt":
        if not isinstance(payload, Mapping):
            raise ValueError("implementation diagnostic receipt must be an object")
        allowed = {
            "schema",
            "receipt_id",
            "prior_decision_id",
            "repository_id",
            "tree_id",
            "failure",
            "failure_id",
            "changed_files",
            "changed_symbols",
            "unresolved_requirements",
        }
        if set(payload).difference(allowed):
            raise ValueError(
                "implementation diagnostic receipt contains unsupported fields"
            )
        if payload.get("schema") != cls.SCHEMA:
            raise ValueError("implementation diagnostic receipt schema is unsupported")
        result = cls(
            prior_decision_id=str(payload.get("prior_decision_id") or ""),
            repository_id=str(payload.get("repository_id") or ""),
            tree_id=str(payload.get("tree_id") or ""),
            failure=payload.get("failure") or {},
            changed_files=tuple(payload.get("changed_files") or ()),
            changed_symbols=tuple(payload.get("changed_symbols") or ()),
            unresolved_requirements=tuple(
                payload.get("unresolved_requirements") or ()
            ),
        )
        if payload.get("failure_id") not in (None, "", result.failure_id):
            raise ValueError("implementation diagnostic failure identity is forged")
        if payload.get("receipt_id") not in (None, "", result.receipt_id):
            raise ValueError("implementation diagnostic receipt identity is forged")
        return result


class ImplementationRetryDeferred(RuntimeError):
    """A typed retry lifecycle stop raised before provider dispatch."""

    def __init__(self, reason: str, *, backoff_seconds: int = 0) -> None:
        super().__init__(reason)
        self.reason = reason
        self.backoff_seconds = backoff_seconds


class WorktreeSubmoduleInitializationDeferred(ImplementationRetryDeferred):
    """Fail closed when a configured implementation dependency is unavailable."""

    def __init__(self, failures: Sequence[Mapping[str, Any]]) -> None:
        normalized_failures = tuple(dict(failure) for failure in failures)
        super().__init__(
            "worktree submodule initialization failed",
            backoff_seconds=30,
        )
        self.failures = normalized_failures


class ValidationProjectDependencyPreflightDeferred(
    ImplementationRetryDeferred
):
    """Fail closed when validation dependencies drift before dispatch."""

    def __init__(
        self,
        receipt: Mapping[str, Any],
        *,
        backoff_seconds: int = (
            PROJECT_DEPENDENCY_PREFLIGHT_BACKOFF_SECONDS
        ),
    ) -> None:
        super().__init__(
            "approved validation environment dependency drift",
            backoff_seconds=backoff_seconds,
        )
        self.receipt = dict(receipt)


class ValidationGeneratedArtifactRestoreError(RuntimeError):
    """A typed pre-validation stop that preserves the candidate worktree."""

    def __init__(self, receipt: Mapping[str, Any]) -> None:
        super().__init__("validation generated artifact restore failed")
        self.receipt = dict(receipt)


@dataclass(frozen=True)
class PortalTask:
    task_id: str
    title: str
    status: str
    completion: str
    priority: str
    track: str
    depends_on: list[str] = field(default_factory=list)
    outputs: list[str] = field(default_factory=list)
    validation: list[str] = field(default_factory=list)
    acceptance: str = ""
    source_line: int = 0
    metadata: dict[str, str] = field(default_factory=dict)
    canonical_task_key: str = ""
    canonical_task_cid: str = ""
    board_namespace: str = "default"


def _task_evidence_output_paths_from_metadata(
    metadata: Mapping[str, Any],
) -> tuple[str, ...]:
    """Return identity-bound evidence file outputs, or no authority.

    The explicit field is necessary but insufficient: every value must be a
    canonical file path repeated in both the task's missing-evidence contract
    and its execution evidence subset.  One malformed, duplicate, forged, or
    control-plane path invalidates the complete typed field.
    """

    normalized_metadata = {
        str(key).strip().lower().replace("_", " "): str(value or "").strip()
        for key, value in metadata.items()
    }
    raw_field = normalized_metadata.get(EVIDENCE_OUTPUTS_METADATA_KEY, "")
    candidates = split_evidence_output_values(raw_field)
    if not candidates:
        return ()

    normalized_candidates = tuple(
        normalize_evidence_output_path(value) for value in candidates
    )
    if (
        any(not path for path in normalized_candidates)
        or len(set(normalized_candidates)) != len(normalized_candidates)
    ):
        return ()

    def requirement_paths(field_name: str) -> set[str]:
        return {
            path
            for value in split_csv(normalized_metadata.get(field_name, ""))
            if (path := normalize_evidence_output_path(value))
        }

    missing_paths = requirement_paths("missing evidence")
    subset_paths = requirement_paths("evidence subset")
    if (
        not missing_paths
        or not subset_paths
        or not set(normalized_candidates).issubset(missing_paths)
        or not set(normalized_candidates).issubset(subset_paths)
    ):
        return ()

    excluded_paths: list[str] = []
    for field_name in (
        "objective heap",
        "evidence inputs",
        "discovery evidence",
        "bundle shard",
    ):
        excluded_paths.extend(
            split_csv(normalized_metadata.get(field_name, ""))
        )
    if any(
        evidence_output_path_is_excluded(path, excluded_paths)
        for path in normalized_candidates
    ):
        return ()
    return normalized_candidates


def task_evidence_output_paths(task: PortalTask) -> tuple[str, ...]:
    """Return validated typed evidence outputs for one parsed task."""

    return _task_evidence_output_paths_from_metadata(task.metadata)


def task_declared_output_paths(task: PortalTask) -> tuple[str, ...]:
    """Return ordinary outputs plus validated typed evidence outputs."""

    return tuple(
        dict.fromkeys(
            [
                *(str(path).strip() for path in task.outputs if str(path).strip()),
                *task_evidence_output_paths(task),
            ]
        )
    )


def task_declares_validation_config_change(task: PortalTask) -> bool:
    """Return whether the task explicitly owns a validation-config path.

    Validation configuration remains fail-closed by default.  The narrow
    exception is an exact path declared in Outputs or Predicted files; a
    provider-suggested/allowed path alone never grants this authority.
    """

    from ..validation.proposal_validation import _VALIDATION_CONFIG_PATHS

    predicted = str(
        (task.metadata or {}).get("predicted files")
        or (task.metadata or {}).get("predicted_files")
        or ""
    )
    declared_paths = tuple(
        dict.fromkeys(
            [
                *task_declared_output_paths(task),
                *(
                    part.strip()
                    for part in predicted.split(",")
                    if part.strip()
                ),
            ]
        )
    )
    for path in declared_paths:
        if (
            not path
            or path.endswith("/")
            or any(character in path for character in "*?[]{}")
        ):
            continue
        if any(
            path == config_path
            or (
                config_path.endswith("/")
                and path.startswith(config_path)
                and len(path) > len(config_path)
            )
            for config_path in _VALIDATION_CONFIG_PATHS
        ):
            return True
    return False


@dataclass(frozen=True)
class ImplementationTimeoutPolicy:
    """One task's bounded implementation lease and progress-idle deadline."""

    configured_timeout_seconds: float
    progress_timeout_seconds: float
    max_timeout_seconds: float
    progress_aware: bool
    source: str

    def to_dict(self) -> dict[str, Any]:
        def duration(value: float) -> str:
            return format(float(value), ".15g")

        return {
            "configured_timeout_seconds": duration(
                self.configured_timeout_seconds
            ),
            "progress_timeout_seconds": duration(
                self.progress_timeout_seconds
            ),
            "max_timeout_seconds": duration(self.max_timeout_seconds),
            "progress_aware": self.progress_aware,
            "source": self.source,
        }


COMPLETION_GAP_EDIT_SCOPE_ROLES = frozenset(
    {
        "completion_gate_gap",
        "completion_gate_gap_retry",
        "completion_gate_gap_review",
    }
)
COMPLETION_GAP_MANUAL_REVIEW_ROLE = "completion_gate_gap_manual_review"


def completion_gap_edit_scope(
    task: PortalTask,
    *,
    repo_root: Path | None = None,
) -> tuple[str, ...] | None:
    """Return exact authorized files for a typed completion-gap task.

    ``None`` means the task is not part of the completion-gap lifecycle.  An
    empty tuple means it is a completion-gap task but has no safe, precise edit
    target and therefore must not be executed.  Exact role matching keeps this
    guard from narrowing ordinary general-purpose implementation tasks.
    """

    metadata = {
        str(key).strip().lower().replace("_", " "): str(value or "").strip()
        for key, value in task.metadata.items()
    }
    role = (
        metadata.get("merge role")
        or metadata.get("proposal source")
        or metadata.get("source")
        or ""
    ).strip().lower()
    if role == COMPLETION_GAP_MANUAL_REVIEW_ROLE:
        return ()
    if role not in COMPLETION_GAP_EDIT_SCOPE_ROLES:
        return None

    raw_paths = split_csv(metadata.get("predicted files", ""))
    if not raw_paths:
        return ()
    root = repo_root.resolve() if repo_root is not None else None
    authorized: list[str] = []
    for raw_path in raw_paths:
        relative = str(raw_path).strip()
        path = Path(relative)
        if (
            not relative
            or relative in {".", ".."}
            or relative.startswith(("/", "\\"))
            or relative.endswith(("/", "\\"))
            or "\\" in relative
            or "\0" in relative
            or "://" in relative
            or re.match(r"^[A-Za-z]:", relative)
            or path.is_absolute()
            or ".." in path.parts
        ):
            return ()
        if root is not None:
            try:
                candidate = (root / path).resolve(strict=False)
                candidate.relative_to(root)
            except (OSError, RuntimeError, ValueError):
                return ()
            if candidate.exists() and candidate.is_dir():
                return ()
        if relative not in authorized:
            authorized.append(relative)
    return tuple(authorized)


def task_implementation_protected_path_conflicts(
    task: PortalTask,
    protected_paths: Sequence[str],
) -> tuple[str, ...]:
    """Return protected files declared by a task's outputs/edit targets."""

    if not protected_paths:
        return ()
    metadata = {
        str(key).strip().lower().replace("_", " "): str(value or "").strip()
        for key, value in task.metadata.items()
    }
    declarations = [
        *task_declared_output_paths(task),
        *split_csv(metadata.get("predicted files", "")),
        *split_csv(metadata.get("predicted outputs", "")),
    ]
    conflicts: list[str] = []
    for protected in protected_paths:
        # Output lists sometimes wrap paths in Markdown or append a short
        # annotation.  Match a path token as well as a normalized exact value.
        token_pattern = re.compile(
            rf"(?<![A-Za-z0-9_.~/-])(?:\./)?{re.escape(protected)}"
            r"(?=$|[\s`'\",;:()\[\]])"
        )
        for declaration in declarations:
            raw = str(declaration or "").strip()
            if not raw:
                continue
            candidates = [raw, *re.findall(r"`([^`]+)`", raw)]
            normalized_candidates = {
                posixpath.normpath(candidate.strip().strip("`'\""))
                for candidate in candidates
                if candidate.strip().strip("`'\"")
            }
            if protected in normalized_candidates or token_pattern.search(raw):
                conflicts.append(protected)
                break
    return tuple(conflicts)


